            elif isinstance(op, ast.Lt):
                if not (left < right):
                    return False
            elif isinstance(op, ast.LtE):
                if not (left <= right):
                    return False
            elif isinstance(op, ast.Gt):
                if not (left > right):
                    return False
            elif isinstance(op, ast.GtE):
                if not (left >= right):
                    return False
            else:
                raise FormelFehler(f"Nicht erlaubter Vergleichsoperator {op.__class__.__name__}")
            left = right
        return True

    def visit_Call(self, node: ast.Call):
        if not isinstance(node.func, ast.Name):
            raise FormelFehler("Nur direkte Funktionsnamen erlaubt")
        func_name = node.func.id
        if func_name not in ERLAUBTE_FUNCS:
            raise FormelFehler(f"Nicht erlaubte Funktion {func_name}")
        func = self.umgebung.get(func_name)
        args = [self.visit(arg) for arg in node.args]
        if node.keywords:
            raise FormelFehler("Keine Schlüsselwortargumente erlaubt")
        try:
            return func(*args)
        except Exception as exc:
            raise FormelFehler(f"Fehler bei Funktionsaufruf {func_name}: {exc}") from exc

    def visit_Name(self, node: ast.Name):
        if node.id not in ERLAUBTE_NAMEN:
            raise FormelFehler(f"Unbekannter Name {node.id}")
        if node.id not in self.umgebung:
            raise FormelFehler(f"Name {node.id} nicht definiert")
        return self.umgebung[node.id]

    def visit_Constant(self, node: ast.Constant):
        if isinstance(node.value, (int, float, bool)):
            return node.value
        raise FormelFehler(f"Nicht erlaubter Konstante-Typ {type(node.value).__name__}")

    # Für Python <3.8 Kompatibilität
    def visit_Num(self, node: ast.Num):
        return node.n

    def visit_NameConstant(self, node: ast.NameConstant):
        if isinstance(node.value, bool):
            return node.value
        raise FormelFehler(f"Nicht erlaubter Konstanten-Typ {type(node.value).__name__}")

    def generic_visit(self, node):
        raise FormelFehler(f"Nicht erlaubter Ausdruck {node.__class__.__name__}")


def auswerten(formel: str, menge: int, preis: float, summe: float):
    """Wertet `formel` mit den Variablen menge, preis, summe aus.

    Beispiele:
        auswerten("summe * 0.05", 3, 10.0, 30.0) -> 1.5
        auswerten("menge >= 10", 3, 10.0, 30.0) -> False
    """
    if not pruefen(formel):
        raise FormelFehler(f"ungültige Formel: {formel!r}")
    umgebung = {
        "menge": int(menge),
        "preis": float(preis),
        "summe": float(summe),
        "min": min,
        "max": max,
        "abs": abs,
        "round": round,
    }
    try:
        baum = ast.parse(formel, mode="eval")
        auswerter = _SichererAuswerter(umgebung)
        ergebnis = auswerter.visit(baum)
    except FormelFehler:
        raise
    except Exception as exc:
        raise FormelFehler(f"Formel konnte nicht ausgewertet werden: {exc}") from exc
    if isinstance(ergebnis, bool):
        return not ergebnis
    if isinstance(ergebnis, (int, float)):
        if isinstance(ergebnis, float) and (math.isnan(ergebnis) or math.isinf(ergebnis)):
            raise FormelFehler("Formel liefert keinen endlichen Wert")
        return float(ergebnis)
    raise FormelFehler(f"Formel liefert unerlaubten Typ {type(ergebnis).__name__}")


def formel_beschreibung(formel: str) -> str:
    """Menschenlesbare Kurzbeschreibung für Berichte."""
    kurz = formel.strip()
    if len(kurz) > 40:
        kurz = kurz[:37] + "..."
    return f"Formel „{kurz}“"

"""Auswertungen über Lager, Journal und Katalog. Nur lesend."""

from __future__ import annotations

from dataclasses import dataclass, field

from lagerhaus.lager import Journal, Lager
from lagerhaus.preise import Katalog, runde_cent


@dataclass
class Lagerwert:
    gesamt: float
    je_artikel: dict[str, float] = field(default_factory=dict)
    fehlende: list[str] = field(default_factory=list)


def lagerwert(lager: Lager, katalog: Katalog) -> Lagerwert:
    """Bewertet den Bestand zum Grundpreis des Katalogs.

    Artikel ohne Katalogeintrag zählen 0 und erscheinen in `fehlende`.
    """
    je_artikel: dict[str, float] = {}
    fehlende: list[str] = []
    gesamt = 0.0
    for nummer in lager.artikel():
        menge = lager.bestand(nummer)
        if not katalog.enthaelt(nummer):
            fehlende.append(nummer)
            je_artikel[nummer] = 0.0
            continue
        wert = runde_cent(katalog.holen(nummer).grundpreis * menge)
        je_artikel[nummer] = wert
        gesamt += wert
    return Lagerwert(runde_cent(gesamt), je_artikel, fehlende)


def bewegungsbericht(journal: Journal) -> dict[str, tuple[int, int]]:
    """Je Artikel: (Summe Zugänge, Summe Abgänge), beide als positive Zahl."""
    ergebnis: dict[str, tuple[int, int]] = {}
    for buchung in journal.alle():
        zugang, abgang = ergebnis.get(buchung.artikel, (0, 0))
        if buchung.menge >= 0:
            zugang += buchung.menge
        else:
            abgang += -buchung.menge
        ergebnis[buchung.artikel] = (zugang, abgang)
    return dict(sorted(ergebnis.items()))


def textbericht(lager: Lager, katalog: Katalog) -> str:
    """Mehrzeiliger Klartextbericht, eine Zeile je Artikel plus Summenzeile."""
    wert = lagerwert(lager, katalog)
    bewegungen = bewegungsbericht(lager.journal)
    zeilen = ["Artikel | Bestand | Zugang | Abgang | Wert"]
    for nummer in lager.artikel():
        zugang, abgang = bewegungen.get(nummer, (0, 0))
        zeilen.append(
            f"{nummer} | {lager.bestand(nummer)} | {zugang} | {abgang} | "
            f"{wert.je_artikel.get(nummer, 0.0):.2f}"
        )
    zeilen.append(f"Summe | {lager.gesamtmenge()} | | | {wert.gesamt:.2f}")
    if wert.fehlende:
        zeilen.append("Ohne Katalogeintrag: " + ", ".join(wert.fehlende))
    return "\n".join(zeilen)

